body.script:

// Single Page Application Client State
const state = {
    view: 'INITIALIZING', // 'LOGIN' | 'SIGNUP' | 'EMPLOYEE_DASHBOARD' | 'HR_ADMIN_DASHBOARD'
    user: null,
    loading: false,
    error: null,
    successMsg: null,

    // Live Domain Data
    profile: null,
    attendance: null,
    leaves: null,
    payroll: null,
    employeesList: null,

    // Modals
    activeModal: null, // 'APPLY_LEAVE' | 'LEAVE_HISTORY' | 'PAYROLL_SLIP' | 'EMPLOYEE_DIRECTORY' | 'ATTENDANCE_LOGS' | 'PENDING_LEAVES' | 'PAYROLL_OVERVIEW'

    signupForm: { empId: '', name: '', email: '', role: 'Employee' },
    loginForm: { email: '' }
};

// Helper to execute JSON-RPC API requests to Dayflow Odoo backend
async function callApi(endpoint, params = {}) {
    try {
        const response = await fetch(endpoint, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            credentials: 'include',
            body: JSON.stringify({
                jsonrpc: '2.0',
                id: Date.now(),
                params: params
            })
        });

        if (!response.ok) {
            throw new Error(`Server HTTP ${response.status}`);
        }

        const data = await response.json();
        if (data.error) {
            const msg = data.error.data?.message || data.error.message || 'Operation failed.';
            throw new Error(msg);
        }
        return data.result;
    } catch (err) {
        console.error(`API Error [${endpoint}]:`, err);
        throw err;
    }
}

// Application Startup Initialization
async function initApp() {
    try {
        const result = await callApi('/dayflow/auth/me');
        if (result && result.status === 'authenticated' && result.uid) {
            state.user = result;
            await loadDashboardData();
            state.view = result.role === 'hr_admin' ? 'HR_ADMIN_DASHBOARD' : 'EMPLOYEE_DASHBOARD';
        } else {
            state.view = 'LOGIN';
        }
    } catch (err) {
        state.view = 'LOGIN';
    } finally {
        render();
    }
}

// Fetch real backend data for Employee or HR Admin
async function loadDashboardData() {
    try {
        const [profRes, attRes, leaveRes, payRes] = await Promise.all([
            callApi('/dayflow/api/profile').catch(() => null),
            callApi('/dayflow/api/attendance/me').catch(() => null),
            callApi('/dayflow/api/leave/me').catch(() => null),
            callApi('/dayflow/api/payroll/me').catch(() => null),
        ]);

        if (profRes && profRes.status === 'success') state.profile = profRes.data || profRes.profile;
        if (attRes && attRes.status === 'success') state.attendance = attRes.data || attRes;
        if (leaveRes && leaveRes.status === 'success') state.leaves = leaveRes.data || leaveRes;
        if (payRes && payRes.status === 'success') state.payroll = payRes.data || payRes;

        if (state.user && state.user.role === 'hr_admin') {
            const empRes = await callApi('/dayflow/api/employees').catch(() => null);
            if (empRes && empRes.status === 'success') state.employeesList = empRes.data?.employees || empRes.employees;
        }
    } catch (err) {
        console.warn('Dashboard data fetch warning:', err);
    }
}

// Action: Login Submit
async function handleLogin(e) {
    e.preventDefault();
    const emailInput = document.getElementById('login-email');
    const passwordInput = document.getElementById('login-password');
    const email = emailInput ? emailInput.value.trim() : '';
    const password = passwordInput ? passwordInput.value.trim() : '';

    state.loginForm = { email };
    state.error = null;
    state.successMsg = null;

    if (!email || !password) {
        state.error = 'EMAIL AND PASSWORD REQUIRED.';
        render();
        return;
    }

    state.loading = true;
    render();

    try {
        const result = await callApi('/dayflow/auth/login', { login: email, password: password });
        if (result && result.status === 'success') {
            state.user = result;
            await loadDashboardData();
            state.view = result.role === 'hr_admin' ? 'HR_ADMIN_DASHBOARD' : 'EMPLOYEE_DASHBOARD';
            state.error = null;
            state.loginForm = { email: '' };
        } else {
            state.error = result.message || 'INVALID LOGIN CREDENTIALS.';
        }
    } catch (err) {
        state.error = err.message || 'AUTHENTICATION FAILED.';
    } finally {
        state.loading = false;
        render();
    }
}

// Action: Signup Submit
async function handleSignup(e) {
    e.preventDefault();
    const empIdInput = document.getElementById('signup-empid');
    const nameInput = document.getElementById('signup-name');
    const emailInput = document.getElementById('signup-email');
    const passwordInput = document.getElementById('signup-password');
    const roleInput = document.getElementById('signup-role');

    const empId = empIdInput ? empIdInput.value.trim() : '';
    const name = nameInput ? nameInput.value.trim() : '';
    const email = emailInput ? emailInput.value.trim() : '';
    const password = passwordInput ? passwordInput.value.trim() : '';
    const role = roleInput ? roleInput.value.trim() : '';

    state.signupForm = { empId, name, email, role: role || 'Employee' };
    state.error = null;
    state.successMsg = null;

    if (!empId || !name || !email || !password || !role) {
        state.error = 'ALL FIELDS ARE REQUIRED.';
        render();
        return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
        state.error = 'INVALID EMAIL FORMAT.';
        render();
        return;
    }

    state.loading = true;
    render();

    try {
        const result = await callApi('/dayflow/auth/register', {
            employee_id: empId,
            name: name,
            email: email,
            password: password,
            role: role
        });

        if (result && result.status === 'success') {
            state.successMsg = 'ACCOUNT REGISTERED! LOGGING IN...';
            state.signupForm = { empId: '', name: '', email: '', role: 'Employee' };
            render();

            const loginRes = await callApi('/dayflow/auth/login', { login: email, password: password });
            if (loginRes && loginRes.status === 'success') {
                state.user = loginRes;
                await loadDashboardData();
                state.view = loginRes.role === 'hr_admin' ? 'HR_ADMIN_DASHBOARD' : 'EMPLOYEE_DASHBOARD';
                state.successMsg = null;
            } else {
                state.view = 'LOGIN';
                state.successMsg = 'ACCOUNT CREATED. PLEASE LOG IN.';
            }
        } else {
            state.error = result.message || 'REGISTRATION FAILED.';
        }
    } catch (err) {
        state.error = err.message || 'REGISTRATION FAILED.';
    } finally {
        state.loading = false;
        render();
    }
}

// Action: Logout
async function handleLogout() {
    state.loading = true;
    render();
    try {
        await callApi('/dayflow/auth/logout');
    } catch (err) {
        console.warn('Logout API call exception:', err);
    } finally {
        state.user = null;
        state.profile = null;
        state.attendance = null;
        state.leaves = null;
        state.payroll = null;
        state.employeesList = null;
        state.activeModal = null;
        state.view = 'LOGIN';
        state.loading = false;
        state.error = null;
        state.successMsg = null;
        render();
    }
}

// Action: Attendance Check In API Call
async function handleCheckIn() {
    state.loading = true;
    render();
    try {
        const res = await callApi('/dayflow/api/attendance/checkin');
        if (res && res.status === 'success') {
            await loadDashboardData();
        } else {
            alert(res.message || 'Check-in failed');
        }
    } catch (err) {
        alert(err.message || 'Check-in error');
    } finally {
        state.loading = false;
        render();
    }
}

// Action: Attendance Check Out API Call
async function handleCheckOut() {
    state.loading = true;
    render();
    try {
        const res = await callApi('/dayflow/api/attendance/checkout');
        if (res && res.status === 'success') {
            await loadDashboardData();
        } else {
            alert(res.message || 'Check-out failed');
        }
    } catch (err) {
        alert(err.message || 'Check-out error');
    } finally {
        state.loading = false;
        render();
    }
}

// Action: Leave Submit Form API Call
async function handleApplyLeaveSubmit(e) {
    e.preventDefault();
    const leaveType = document.getElementById('leave-type').value;
    const dateFrom = document.getElementById('leave-from').value;
    const dateTo = document.getElementById('leave-to').value;
    const remarks = document.getElementById('leave-remarks').value;

    if (!leaveType || !dateFrom || !dateTo) {
        alert('Please fill all required fields');
        return;
    }

    state.loading = true;
    render();
    try {
        const res = await callApi('/dayflow/api/leave', {
            leave_type: leaveType,
            date_from: dateFrom,
            date_to: dateTo,
            remarks: remarks
        });

        if (res && res.status === 'success') {
            state.activeModal = null;
            await loadDashboardData();
        } else {
            alert(res.message || 'Leave submission failed.');
        }
    } catch (err) {
        alert(err.message || 'Leave submission failed.');
    } finally {
        state.loading = false;
        render();
    }
}

// Action: HR Admin Leave Approve API Call
async function handleApproveLeave(leaveId) {
    state.loading = true;
    render();
    try {
        const res = await callApi(`/dayflow/api/leave/${leaveId}/approve`, { id: leaveId });
        if (res && res.status === 'success') {
            await loadDashboardData();
        } else {
            alert(res.message || 'Approval failed.');
        }
    } catch (err) {
        alert(err.message || 'Approval error.');
    } finally {
        state.loading = false;
        render();
    }
}

// Action: HR Admin Leave Reject API Call
async function handleRejectLeave(leaveId) {
    state.loading = true;
    render();
    try {
        const res = await callApi(`/dayflow/api/leave/${leaveId}/reject`, { id: leaveId });
        if (res && res.status === 'success') {
            await loadDashboardData();
        } else {
            alert(res.message || 'Rejection failed.');
        }
    } catch (err) {
        alert(err.message || 'Rejection error.');
    } finally {
        state.loading = false;
        render();
    }
}

// Open & Close Modals
function openModal(name) {
    state.activeModal = name;
    render();
}

function closeModal() {
    state.activeModal = null;
    render();
}

// Render UI Views based on current state
function render() {
    const root = document.getElementById('app-root');
    if (!root) return;

    if (state.view === 'INITIALIZING') {
        root.innerHTML = `
            <div class="page-loader">
                <div class="loader-box">
                    <div class="spinner-block" style="width: 44px; height: 44px;"></div>
                    <h2 style="margin-top: 1rem; font-weight: 900; text-transform: uppercase;">DAYFLOW HRMS</h2>
                    <p style="font-size: 0.85rem; font-weight: 700; color: var(--text-muted); margin-top: 0.25rem;">EVERY WORKDAY, PERFECTLY ALIGNED.</p>
                </div>
            </div>
        `;
        return;
    }

    let contentHtml = '';

    // Navbar Header for Authenticated Session
    const navbarHtml = state.user ? `
        <header class="navbar">
            <div class="brand-logo" onclick="loadDashboardData().then(render)">
                DAYFLOW
                <span class="brand-badge">HRMS</span>
                <span class="tagline-text">| Every workday, perfectly aligned.</span>
            </div>
            <div class="user-nav-profile">
                <span class="badge-role ${state.user.role === 'hr_admin' ? 'badge-admin' : 'badge-employee'}">
                    ${state.user.role === 'hr_admin' ? 'HR / ADMIN' : 'EMPLOYEE'}
                </span>
                <div style="text-align: right;">
                    <div style="font-weight: 900; font-size: 0.95rem; text-transform: uppercase;">${escapeHtml(state.user.name || state.user.login)}</div>
                    <div class="mono" style="font-size: 0.8rem; font-weight: 800; color: var(--text-muted);">ID: ${escapeHtml(state.user.employee_code || 'N/A')}</div>
                </div>
                <button class="btn-brutal btn-logout" onclick="handleLogout()">LOGOUT</button>
            </div>
        </header>
    ` : '';

    if (state.view === 'LOGIN') {
        contentHtml = `
            <div class="auth-wrapper">
                <div class="auth-card">
                    <div class="auth-header">
                        <div class="brand-logo" style="margin-bottom: 0.75rem;">
                            DAYFLOW
                            <span class="brand-badge">SYSTEM</span>
                        </div>
                        <h1 class="auth-title">AUTHENTICATE</h1>
                        <p class="auth-subtitle">Every workday, perfectly aligned.</p>
                    </div>

                    ${state.error ? `<div class="alert alert-error">❌ ${escapeHtml(state.error)}</div>` : ''}
                    ${state.successMsg ? `<div class="alert alert-success">✓ ${escapeHtml(state.successMsg)}</div>` : ''}

                    <form onsubmit="handleLogin(event)">
                        <div class="form-group">
                            <label class="form-label" for="login-email">WORK EMAIL ADDRESS</label>
                            <input type="email" id="login-email" class="form-input" placeholder="user@dayflow.org" required="required" autocomplete="email" value="${escapeHtml(state.loginForm.email || '')}" />
                        </div>
                        <div class="form-group">
                            <label class="form-label" for="login-password">PASSWORD</label>
                            <input type="password" id="login-password" class="form-input" placeholder="••••••••" required="required" autocomplete="current-password" />
                        </div>
                        <button type="submit" class="btn-submit" ${state.loading ? 'disabled' : ''}>
                            ${state.loading ? '<span class="spinner-block"></span> AUTHENTICATING...' : 'ACCESS SYSTEM'}
                        </button>
                    </form>

                    <div class="auth-footer">
                        NEW EMPLOYEE? 
                        <span class="auth-link" onclick="state.view='SIGNUP'; state.error=null; render();">CREATE ACCOUNT</span>
                    </div>
                </div>
            </div>
        `;
    } else if (state.view === 'SIGNUP') {
        contentHtml = `
            <div class="auth-wrapper">
                <div class="auth-card">
                    <div class="auth-header">
                        <div class="brand-logo" style="margin-bottom: 0.75rem;">
                            DAYFLOW
                            <span class="brand-badge">REGISTRATION</span>
                        </div>
                        <h1 class="auth-title">NEW PROFILE</h1>
                        <p class="auth-subtitle">Register user identity &amp; linked HR profile</p>
                    </div>

                    ${state.error ? `<div class="alert alert-error">❌ ${escapeHtml(state.error)}</div>` : ''}

                    <form onsubmit="handleSignup(event)">
                        <div class="form-group">
                            <label class="form-label" for="signup-empid">CANONICAL EMPLOYEE ID</label>
                            <input type="text" id="signup-empid" class="form-input mono" placeholder="e.g. EMP101" required="required" value="${escapeHtml(state.signupForm.empId || '')}" />
                        </div>
                        <div class="form-group">
                            <label class="form-label" for="signup-name">FULL NAME</label>
                            <input type="text" id="signup-name" class="form-input" placeholder="ALICE SMITH" required="required" value="${escapeHtml(state.signupForm.name || '')}" />
                        </div>
                        <div class="form-group">
                            <label class="form-label" for="signup-email">WORK EMAIL ADDRESS</label>
                            <input type="email" id="signup-email" class="form-input" placeholder="alice@dayflow.org" required="required" value="${escapeHtml(state.signupForm.email || '')}" />
                        </div>
                        <div class="form-group">
                            <label class="form-label" for="signup-password">PASSWORD</label>
                            <input type="password" id="signup-password" class="form-input" placeholder="••••••••" required="required" minlength="6" />
                        </div>
                        <div class="form-group">
                            <label class="form-label" for="signup-role">AUTHORIZATION ROLE</label>
                            <select id="signup-role" class="form-select">
                                <option value="Employee" ${state.signupForm.role === 'Employee' ? 'selected' : ''}>EMPLOYEE</option>
                                <option value="HR/Admin" ${state.signupForm.role === 'HR/Admin' ? 'selected' : ''}>HR / ADMIN</option>
                            </select>
                        </div>
                        <button type="submit" class="btn-submit" ${state.loading ? 'disabled' : ''}>
                            ${state.loading ? '<span class="spinner-block"></span> REGISTERING...' : 'REGISTER PROFILE'}
                        </button>
                    </form>

                    <div class="auth-footer">
                        ALREADY REGISTERED? 
                        <span class="auth-link" onclick="state.view='LOGIN'; state.error=null; render();">SIGN IN</span>
                    </div>
                </div>
            </div>
        `;
    } else if (state.view === 'EMPLOYEE_DASHBOARD') {
        const attToday = state.attendance?.today || {};
        const isCheckedIn = attToday.is_checked_in;
        const checkInTime = attToday.check_in ? attToday.check_in.split(' ')[1]?.slice(0, 5) : 'NOT LOGGED';
        const workedHours = attToday.worked_hours || 0;
        const attStatus = (attToday.status || 'absent').toUpperCase().replace('_', ' ');

        const pendingLeaves = state.leaves?.pending_count || 0;
        const approvedLeaves = state.leaves?.approved_count || 0;

        const latestPayroll = state.payroll?.latest;
        const salaryText = latestPayroll ? `${latestPayroll.currency}${latestPayroll.net_salary.toLocaleString()}` : '₹0';
        const salaryPeriod = latestPayroll ? latestPayroll.pay_period : 'N/A';
        const salaryState = (latestPayroll?.state || 'DRAFT').toUpperCase();

        contentHtml = `
            ${navbarHtml}
            <main class="dashboard-container">
                <section class="welcome-hero">
                    <span class="hero-tag">EMPLOYEE PORTAL</span>
                    <h1 class="hero-title">DAYFLOW OPERATIONS</h1>
                    <p style="font-size: 1.1rem; font-weight: 700; color: var(--text-black);">
                        WELCOME, <strong>${escapeHtml(state.user.name || 'EMPLOYEE')}</strong> | 
                        ID: <span class="mono" style="background: var(--accent-yellow); padding: 0.1rem 0.5rem; border: 2px solid #000;">${escapeHtml(state.user.employee_code || 'N/A')}</span> | 
                        EMAIL: <span class="mono">${escapeHtml(state.user.login)}</span>
                    </p>
                </section>

                <div class="grid-2x2">
                    <!-- TODAY'S ATTENDANCE -->
                    <div class="brutal-card">
                        <div>
                            <div class="card-header-bar">
                                <div class="card-title">⏱️ TODAY'S ATTENDANCE</div>
                                <span class="badge-role ${isCheckedIn ? 'badge-employee' : 'badge-neutral'}">${attStatus}</span>
                            </div>
                            <div style="margin: 1.25rem 0;">
                                ${isCheckedIn ? `
                                    <button class="btn-action-big checkout-btn" onclick="handleCheckOut()">
                                        ⏹️ [ CHECK OUT ]
                                    </button>
                                ` : `
                                    <button class="btn-action-big" onclick="handleCheckIn()" ${attToday.check_out ? 'disabled style=\"opacity:0.6; cursor:not-allowed;\"' : ''}>
                                        ${attToday.check_out ? '✓ [ COMPLETED TODAY ]' : '▶️ [ CHECK IN ]'}
                                    </button>
                                `}
                            </div>
                            <div class="mono" style="font-weight: 800; font-size: 1rem; margin-bottom: 0.5rem;">
                                CHECK-IN TIME: <span style="background: var(--accent-green); padding: 0.2rem 0.6rem; border: 2px solid #000;">${checkInTime}</span>
                            </div>
                            <div class="mono" style="font-weight: 800; font-size: 0.9rem; color: var(--text-muted);">
                                WORKED TODAY: ${workedHours} HRS
                            </div>
                        </div>
                        <div style="margin-top: 1.5rem; border-top: 2px solid #000; padding-top: 0.75rem;">
                            <button class="btn-brutal" style="font-size: 0.8rem; padding: 0.4rem 0.8rem;" onclick="openModal('ATTENDANCE_LOGS')">VIEW ATTENDANCE LOGS</button>
                        </div>
                    </div>

                    <!-- LEAVE STATUS -->
                    <div class="brutal-card">
                        <div>
                            <div class="card-header-bar">
                                <div class="card-title">📅 LEAVE STATUS</div>
                                <span class="badge-role badge-yellow">LEAVES</span>
                            </div>
                            <div class="stat-box">
                                <span class="stat-box-yellow">${pendingLeaves} PENDING</span>
                            </div>
                            <div style="font-weight: 800; font-size: 0.95rem; text-transform: uppercase;">
                                APPROVED THIS YEAR: ${approvedLeaves} REQUESTS
                            </div>
                        </div>
                        <div style="margin-top: 1.5rem; border-top: 2px solid #000; padding-top: 0.75rem; display: flex; gap: 0.5rem;">
                            <button class="btn-brutal" style="font-size: 0.8rem; padding: 0.4rem 0.8rem; background: var(--accent-yellow);" onclick="openModal('APPLY_LEAVE')">+ APPLY LEAVE</button>
                            <button class="btn-brutal" style="font-size: 0.8rem; padding: 0.4rem 0.8rem;" onclick="openModal('LEAVE_HISTORY')">HISTORY</button>
                        </div>
                    </div>

                    <!-- PAYROLL SUMMARY -->
                    <div class="brutal-card">
                        <div>
                            <div class="card-header-bar">
                                <div class="card-title">💳 PAYROLL / SALARY</div>
                                <span class="badge-role badge-employee">${salaryState}</span>
                            </div>
                            <div class="stat-box">
                                <span class="stat-box-green">${salaryText}</span>
                            </div>
                            <div style="font-weight: 800; font-size: 0.95rem; text-transform: uppercase;">
                                PERIOD: ${salaryPeriod} | NET DISPATCH
                            </div>
                        </div>
                        <div style="margin-top: 1.5rem; border-top: 2px solid #000; padding-top: 0.75rem;">
                            <button class="btn-brutal" style="font-size: 0.8rem; padding: 0.4rem 0.8rem;" onclick="openModal('PAYROLL_SLIP')">VIEW SALARY SLIP</button>
                        </div>
                    </div>

                    <!-- PROFILE CONTRACT -->
                    <div class="brutal-card">
                        <div>
                            <div class="card-header-bar">
                                <div class="card-title">👤 PROFILE INFO</div>
                                <span class="badge-role badge-blue">LINKED</span>
                            </div>
                            <div style="display: flex; flex-direction: column; gap: 0.5rem; margin-top: 0.5rem; font-weight: 700;">
                                <div>FULL NAME: <strong>${escapeHtml(state.profile?.name || state.user.name)}</strong></div>
                                <div>CANONICAL CODE: <span class="mono" style="background: #fff; padding: 0.1rem 0.4rem; border: 2px solid #000;">${escapeHtml(state.profile?.employee_code || state.user.employee_code || 'N/A')}</span></div>
                                <div>EMPLOYMENT: <span style="text-transform: uppercase;">${escapeHtml((state.profile?.df_employment_type || 'full_time').replace('_', ' '))}</span></div>
                                <div>SECURITY ROLE: <strong>${escapeHtml(state.user.role.toUpperCase())}</strong></div>
                                ${state.profile?.df_phone ? `<div>PHONE: <span class="mono">${escapeHtml(state.profile.df_phone)}</span></div>` : ''}
                            </div>
                        </div>
                    </div>
                </div>
            </main>
        `;
    } else if (state.view === 'HR_ADMIN_DASHBOARD') {
        const hrStats = state.attendance?.hr_stats || {};
        const totalEmp = hrStats.total_employees || (state.employeesList?.length || 0);
        const presentToday = hrStats.present_today || 0;
        const onLeave = hrStats.on_leave_today || 0;
        const pendingLeaves = state.leaves?.pending_approvals?.length || 0;

        contentHtml = `
            ${navbarHtml}
            <main class="dashboard-container">
                <section class="welcome-hero">
                    <span class="hero-tag" style="background: var(--accent-purple); color: #fff;">HR CONTROL CENTER</span>
                    <h1 class="hero-title">DAYFLOW SYSTEM ADMINISTRATION</h1>
                    <p style="font-size: 1.1rem; font-weight: 700; color: var(--text-black);">
                        ADMINISTRATOR: <strong>${escapeHtml(state.user.name || state.user.login)}</strong> | 
                        ADMIN ID: <span class="mono" style="background: var(--accent-purple); color: #fff; padding: 0.1rem 0.5rem; border: 2px solid #000;">${escapeHtml(state.user.employee_code || 'ADM001')}</span>
                    </p>
                </section>

                <!-- HR METRICS OVERVIEW GRID -->
                <div class="stat-grid-4">
                    <div class="brutal-card" style="padding: 1.5rem;">
                        <div class="card-title" style="font-size: 0.95rem; color: var(--text-muted);">EMPLOYEES</div>
                        <div class="stat-box" style="font-size: 3rem; margin: 0.5rem 0 0 0;">
                            <span class="stat-box-yellow">${totalEmp}</span>
                        </div>
                    </div>
                    <div class="brutal-card" style="padding: 1.5rem;">
                        <div class="card-title" style="font-size: 0.95rem; color: var(--text-muted);">PRESENT TODAY</div>
                        <div class="stat-box" style="font-size: 3rem; margin: 0.5rem 0 0 0;">
                            <span class="stat-box-green">${presentToday}</span>
                        </div>
                    </div>
                    <div class="brutal-card" style="padding: 1.5rem;">
                        <div class="card-title" style="font-size: 0.95rem; color: var(--text-muted);">ON LEAVE</div>
                        <div class="stat-box" style="font-size: 3rem; margin: 0.5rem 0 0 0;">
                            <span style="background: var(--accent-blue); color: #fff; display: inline-block; padding: 0.2rem 0.8rem; border: 3px solid #000; box-shadow: 3px 3px 0px #000;">${onLeave}</span>
                        </div>
                    </div>
                    <div class="brutal-card" style="padding: 1.5rem;">
                        <div class="card-title" style="font-size: 0.95rem; color: var(--text-muted);">PENDING LEAVE</div>
                        <div class="stat-box" style="font-size: 3rem; margin: 0.5rem 0 0 0;">
                            <span class="stat-box-rose">${pendingLeaves}</span>
                        </div>
                    </div>
                </div>

                <!-- HR NAVIGATION & MANAGEMENT GRID -->
                <div class="grid-2x2">
                    <div class="brutal-card">
                        <div>
                            <div class="card-header-bar">
                                <div class="card-title">👥 EMPLOYEES</div>
                                <button class="btn-brutal" style="padding: 0.3rem 0.8rem; font-size: 0.8rem;" onclick="openModal('EMPLOYEE_DIRECTORY')">DIRECTORY</button>
                            </div>
                            <p style="font-weight: 700; color: var(--text-muted);">View, inspect canonical profiles, employee IDs, and role privileges across the company.</p>
                        </div>
                    </div>
                    <div class="brutal-card">
                        <div>
                            <div class="card-header-bar">
                                <div class="card-title">⏱️ ATTENDANCE</div>
                                <button class="btn-brutal" style="padding: 0.3rem 0.8rem; font-size: 0.8rem;" onclick="openModal('ATTENDANCE_LOGS')">LOGS</button>
                            </div>
                            <p style="font-weight: 700; color: var(--text-muted);">Audit daily check-in times, worked hours, and employee check-in compliance logs.</p>
                        </div>
                    </div>
                    <div class="brutal-card">
                        <div>
                            <div class="card-header-bar">
                                <div class="card-title">📋 LEAVE APPROVALS</div>
                                <button class="btn-brutal" style="padding: 0.3rem 0.8rem; font-size: 0.8rem; background: var(--accent-yellow);" onclick="openModal('PENDING_LEAVES')">${pendingLeaves} NEW</button>
                            </div>
                            <p style="font-weight: 700; color: var(--text-muted);">Review pending leave submissions and approve or reject time-off requests with real-time audit logs.</p>
                        </div>
                    </div>
                    <div class="brutal-card">
                        <div>
                            <div class="card-header-bar">
                                <div class="card-title">💼 PAYROLL</div>
                                <button class="btn-brutal" style="padding: 0.3rem 0.8rem; font-size: 0.8rem; background: var(--accent-green);" onclick="openModal('PAYROLL_OVERVIEW')">VIEW SLIPS</button>
                            </div>
                            <p style="font-weight: 700; color: var(--text-muted);">Inspect salary structures, basic pay, deductions, gross totals, and net payout records.</p>
                        </div>
                    </div>
                </div>
            </main>
        `;
    }

    // Append Modals if Active
    let modalHtml = '';
    if (state.activeModal === 'APPLY_LEAVE') {
        modalHtml = `
            <div class="modal-overlay" onclick="if(event.target === this) closeModal()">
                <div class="modal-box">
                    <div class="modal-header">
                        <div class="modal-title">📝 APPLY FOR TIME OFF</div>
                        <button class="btn-close-modal" onclick="closeModal()">✕</button>
                    </div>
                    <form onsubmit="handleApplyLeaveSubmit(event)">
                        <div class="form-group">
                            <label class="form-label" for="leave-type">LEAVE CATEGORY</label>
                            <select id="leave-type" class="form-select" required="required">
                                <option value="paid">PAID LEAVE</option>
                                <option value="sick">SICK LEAVE</option>
                                <option value="unpaid">UNPAID LEAVE</option>
                            </select>
                        </div>
                        <div class="form-group" style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;">
                            <div>
                                <label class="form-label" for="leave-from">FROM DATE</label>
                                <input type="date" id="leave-from" class="form-input" required="required" />
                            </div>
                            <div>
                                <label class="form-label" for="leave-to">TO DATE</label>
                                <input type="date" id="leave-to" class="form-input" required="required" />
                            </div>
                        </div>
                        <div class="form-group">
                            <label class="form-label" for="leave-remarks">REASON / REMARKS</label>
                            <textarea id="leave-remarks" class="form-textarea" rows="3" placeholder="Provide leave context..."></textarea>
                        </div>
                        <button type="submit" class="btn-submit" ${state.loading ? 'disabled' : ''}>
                            ${state.loading ? '<span class="spinner-block"></span> SUBMITTING...' : 'SUBMIT REQUEST'}
                        </button>
                    </form>
                </div>
            </div>
        `;
    } else if (state.activeModal === 'LEAVE_HISTORY') {
        const myLeaves = state.leaves?.my_leaves || [];
        modalHtml = `
            <div class="modal-overlay" onclick="if(event.target === this) closeModal()">
                <div class="modal-box" style="max-width: 800px;">
                    <div class="modal-header">
                        <div class="modal-title">📅 MY LEAVE HISTORY</div>
                        <button class="btn-close-modal" onclick="closeModal()">✕</button>
                    </div>
                    ${myLeaves.length === 0 ? '<p style=\"font-weight:700;\">No leave requests found.</p>' : `
                        <table class="brutal-table">
                            <thead>
                                <tr>
                                    <th>TYPE</th>
                                    <th>DATES</th>
                                    <th>DAYS</th>
                                    <th>STATUS</th>
                                    <th>DECIDED BY</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${myLeaves.map(l => `
                                    <tr>
                                        <td><strong>${escapeHtml(l.leave_type_label)}</strong></td>
                                        <td class="mono">${escapeHtml(l.date_from)} → ${escapeHtml(l.date_to)}</td>
                                        <td class="mono">${l.number_of_days}</td>
                                        <td>
                                            <span class="badge-role ${l.state === 'approved' ? 'badge-employee' : (l.state === 'rejected' ? 'badge-rose' : 'badge-yellow')}" style="padding:0.2rem 0.5rem; font-size:0.75rem;">
                                                ${escapeHtml(l.state.toUpperCase())}
                                            </span>
                                        </td>
                                        <td>${escapeHtml(l.approved_by || '—')}</td>
                                    </tr>
                                `).join('')}
                            </tbody>
                        </table>
                    `}
                </div>
            </div>
        `;
    } else if (state.activeModal === 'ATTENDANCE_LOGS') {
        const history = state.attendance?.history || [];
        modalHtml = `
            <div class="modal-overlay" onclick="if(event.target === this) closeModal()">
                <div class="modal-box" style="max-width: 750px;">
                    <div class="modal-header">
                        <div class="modal-title">⏱️ ATTENDANCE LOGS</div>
                        <button class="btn-close-modal" onclick="closeModal()">✕</button>
                    </div>
                    ${history.length === 0 ? '<p style=\"font-weight:700;\">No attendance records found.</p>' : `
                        <table class="brutal-table">
                            <thead>
                                <tr>
                                    <th>DATE</th>
                                    <th>CHECK IN</th>
                                    <th>CHECK OUT</th>
                                    <th>HOURS</th>
                                    <th>STATUS</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${history.map(h => `
                                    <tr>
                                        <td class="mono">${escapeHtml(h.date)}</td>
                                        <td class="mono">${escapeHtml(h.check_in ? h.check_in.split(' ')[1] : '—')}</td>
                                        <td class="mono">${escapeHtml(h.check_out ? h.check_out.split(' ')[1] : '—')}</td>
                                        <td class="mono">${h.worked_hours}</td>
                                        <td>
                                            <span class="badge-role ${h.status === 'present' ? 'badge-employee' : (h.status === 'leave' ? 'badge-blue' : 'badge-neutral')}" style="padding:0.2rem 0.5rem; font-size:0.75rem;">
                                                ${escapeHtml(h.status.toUpperCase())}
                                            </span>
                                        </td>
                                    </tr>
                                `).join('')}
                            </tbody>
                        </table>
                    `}
                </div>
            </div>
        `;
    } else if (state.activeModal === 'PAYROLL_SLIP' || state.activeModal === 'PAYROLL_OVERVIEW') {
        const pay = state.payroll?.latest;
        modalHtml = `
            <div class="modal-overlay" onclick="if(event.target === this) closeModal()">
                <div class="modal-box">
                    <div class="modal-header">
                        <div class="modal-title">💳 SALARY STATEMENT</div>
                        <button class="btn-close-modal" onclick="closeModal()">✕</button>
                    </div>
                    ${!pay ? '<p style=\"font-weight:700;\">No payroll records published yet.</p>' : `
                        <div style="border: 3px solid #000; padding: 1.5rem; background: #fafaf5; margin-bottom: 1rem;">
                            <div style="display:flex; justify-content:space-between; margin-bottom:1rem; border-bottom:2px solid #000; padding-bottom:0.5rem;">
                                <strong>PAY PERIOD: <span class="mono">${escapeHtml(pay.pay_period)}</span></strong>
                                <span class="badge-role badge-employee">${escapeHtml(pay.state.toUpperCase())}</span>
                            </div>
                            <div style="display:grid; grid-template-columns: 1fr 1fr; gap: 0.75rem; font-size: 0.95rem; font-weight:700;">
                                <div>BASIC SALARY:</div>
                                <div class="mono" style="text-align:right;">${pay.currency}${pay.basic_salary.toLocaleString()}</div>
                                <div>HRA ALLOWANCE:</div>
                                <div class="mono" style="text-align:right;">${pay.currency}${pay.house_rent_allowance.toLocaleString()}</div>
                                <div>TRANSPORT:</div>
                                <div class="mono" style="text-align:right;">${pay.currency}${pay.transport_allowance.toLocaleString()}</div>
                                <div style="border-top:2px solid #000; padding-top:0.3rem;"><strong>GROSS SALARY:</strong></div>
                                <div class="mono" style="border-top:2px solid #000; padding-top:0.3rem; text-align:right;"><strong>${pay.currency}${pay.gross_salary.toLocaleString()}</strong></div>
                                <div style="color:var(--accent-rose);">PF DEDUCTION:</div>
                                <div class="mono" style="text-align:right; color:var(--accent-rose);">${pay.currency}${pay.provident_fund.toLocaleString()}</div>
                                <div style="color:var(--accent-rose);">TAX DEDUCTION:</div>
                                <div class="mono" style="text-align:right; color:var(--accent-rose);">${pay.currency}${pay.tax_deduction.toLocaleString()}</div>
                                <div style="border-top:3px solid #000; padding-top:0.5rem; font-size:1.1rem;"><strong>NET PAYOUT:</strong></div>
                                <div class="mono" style="border-top:3px solid #000; padding-top:0.5rem; text-align:right; font-size:1.1rem; background:var(--accent-green); padding:0.2rem 0.5rem; border:2px solid #000;"><strong>${pay.currency}${pay.net_salary.toLocaleString()}</strong></div>
                            </div>
                        </div>
                    `}
                </div>
            </div>
        `;
    } else if (state.activeModal === 'EMPLOYEE_DIRECTORY') {
        const emps = state.employeesList || [];
        modalHtml = `
            <div class="modal-overlay" onclick="if(event.target === this) closeModal()">
                <div class="modal-box" style="max-width: 850px;">
                    <div class="modal-header">
                        <div class="modal-title">👥 EMPLOYEE DIRECTORY</div>
                        <button class="btn-close-modal" onclick="closeModal()">✕</button>
                    </div>
                    <table class="brutal-table">
                        <thead>
                            <tr>
                                <th>CODE</th>
                                <th>NAME</th>
                                <th>EMAIL</th>
                                <th>ROLE</th>
                                <th>EMPLOYMENT</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${emps.map(e => `
                                <tr>
                                    <td class="mono"><strong>${escapeHtml(e.employee_code)}</strong></td>
                                    <td>${escapeHtml(e.name)}</td>
                                    <td class="mono">${escapeHtml(e.work_email)}</td>
                                    <td>
                                        <span class="badge-role ${e.df_role === 'hr_admin' ? 'badge-admin' : 'badge-employee'}" style="padding:0.15rem 0.4rem; font-size:0.7rem;">
                                            ${escapeHtml(e.df_role.toUpperCase())}
                                        </span>
                                    </td>
                                    <td style="text-transform: uppercase;">${escapeHtml(e.df_employment_type.replace('_', ' '))}</td>
                                </tr>
                            `).join('')}
                        </tbody>
                    </table>
                </div>
            </div>
        `;
    } else if (state.activeModal === 'PENDING_LEAVES') {
        const pendings = state.leaves?.pending_approvals || [];
        modalHtml = `
            <div class="modal-overlay" onclick="if(event.target === this) closeModal()">
                <div class="modal-box" style="max-width: 850px;">
                    <div class="modal-header">
                        <div class="modal-title">📋 PENDING LEAVE APPROVALS</div>
                        <button class="btn-close-modal" onclick="closeModal()">✕</button>
                    </div>
                    ${pendings.length === 0 ? '<p style=\"font-weight:700;\">No pending leave requests awaiting approval.</p>' : `
                        <table class="brutal-table">
                            <thead>
                                <tr>
                                    <th>EMPLOYEE</th>
                                    <th>TYPE</th>
                                    <th>DATES</th>
                                    <th>DAYS</th>
                                    <th>ACTIONS</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${pendings.map(p => `
                                    <tr>
                                        <td>
                                            <strong>${escapeHtml(p.employee_name)}</strong>
                                            <div class="mono" style="font-size:0.75rem; color:var(--text-muted);">ID: ${escapeHtml(p.employee_code)}</div>
                                        </td>
                                        <td>${escapeHtml(p.leave_type_label)}</td>
                                        <td class="mono">${escapeHtml(p.date_from)} → ${escapeHtml(p.date_to)}</td>
                                        <td class="mono">${p.number_of_days}</td>
                                        <td>
                                            <div style="display:flex; gap:0.4rem;">
                                                <button class="btn-brutal" style="background:var(--accent-green); padding:0.25rem 0.6rem; font-size:0.75rem;" onclick="handleApproveLeave(${p.id})">APPROVE</button>
                                                <button class="btn-brutal" style="background:var(--accent-rose); color:#fff; padding:0.25rem 0.6rem; font-size:0.75rem;" onclick="handleRejectLeave(${p.id})">REJECT</button>
                                            </div>
                                        </td>
                                    </tr>
                                `).join('')}
                            </tbody>
                        </table>
                    `}
                </div>
            </div>
        `;
    }

    root.innerHTML = contentHtml + modalHtml;
}

function escapeHtml(str) {
    if (!str) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// Run init on DOM load
document.addEventListener('DOMContentLoaded', initApp);
